        fact("¿Qué principio exige adaptar el trabajo a la persona?", "La acción preventiva debe tener en cuenta las características individuales y adaptar el trabajo a la persona", ["La persona debe adaptarse siempre al puesto sin cambios", "La prevención se limita a entregar equipos", "La organización puede ignorar la evolución técnica"], "El artículo 15.1.d incluye adaptar el trabajo a la persona entre los principios de la acción preventiva.", "Artículo 15.1.d", "legal_provision", "intermediate"),
        fact("¿Qué obligación tiene el empresario respecto de la evaluación de riesgos?", "Debe realizar una evaluación inicial y actualizarla cuando cambien las condiciones o se produzcan daños", ["Solo debe evaluarlos tras una inspección", "Puede sustituirla por una encuesta informal", "No necesita conservar sus resultados"], "El artículo 16 exige evaluar inicialmente y revisar la evaluación cuando cambien las condiciones o se produzcan daños para la salud.", "Artículo 16.2.a", "legal_provision", "intermediate"),
        fact("¿Qué derecho tienen los trabajadores frente a los riesgos laborales?", "Una protección eficaz en materia de seguridad y salud en el trabajo", ["Renunciar anticipadamente a toda protección", "Elegir qué normas legales se aplican", "Obtener siempre una indemnización sin daño"], "El artículo 14 reconoce el derecho de los trabajadores a una protección eficaz en materia de seguridad y salud.", "Artículo 14.1", "legal_provision", "basic"),
        fact("¿Qué debe proporcionar el empresario cuando un equipo de protección individual es necesario?", "Equipos adecuados y gratuitos, además de velar por su uso efectivo", ["Equipos que el trabajador debe comprar siempre", "Solo una recomendación verbal", "Un equipo común sin adaptación al riesgo"], "El artículo 17 obliga a proporcionar equipos adecuados y a velar por su uso efectivo cuando los riesgos no puedan evitarse suficientemente.", "Artículo 17.2", "legal_provision", "intermediate"),
        fact("¿Qué obligación tiene el empresario sobre la información preventiva?", "Informar a los trabajadores sobre los riesgos y las medidas de protección y prevención", ["Informar solo después de un accidente", "Reservar toda información a la dirección", "Sustituir la información por una cláusula contractual"], "El artículo 18 exige información sobre los riesgos, las medidas y las medidas de emergencia aplicables al puesto.", "Artículo 18.1", "legal_provision", "basic"),
        fact("¿Qué debe incluir la formación preventiva?", "Ser teórica y práctica, suficiente y adecuada al puesto o función", ["Solo una lectura voluntaria de carteles", "Formación idéntica sin atender al puesto", "Una prueba médica en lugar de formación"], "El artículo 19 exige formación teórica y práctica, suficiente y adecuada, al inicio y cuando cambien funciones o equipos.", "Artículo 19.1", "legal_provision", "intermediate"),
        fact("¿Qué debe hacer el trabajador con las máquinas y equipos de protección?", "Utilizarlos correctamente y conforme a su naturaleza y riesgos previsibles", ["Modificar sus dispositivos de seguridad", "Desconectarlos para trabajar más rápido", "Prestarles uso ajeno al puesto sin autorización"], "El artículo 29 obliga al trabajador a usar adecuadamente máquinas, aparatos, herramientas, sustancias y equipos de protección.", "Artículo 29.2.2", "legal_provision", "basic"),
        fact("¿Qué protección especial prevé la ley para la maternidad cuando existe riesgo?", "Evaluar el riesgo y adoptar medidas, incluyendo adaptación, cambio de puesto o suspensión cuando proceda", ["Excluir automáticamente a la trabajadora del empleo", "Eliminar la evaluación por tratarse de un riesgo privado", "Aplicar siempre una reducción salarial"], "El artículo 26 establece una protección específica de la maternidad mediante evaluación y medidas preventivas progresivas.", "Artículo 26", "legal_provision", "advanced"),
