        fact("¿Qué propiedad de TLS 1.3 impide que una clave de sesión comprometida revele normalmente sesiones anteriores?", "El secreto hacia adelante proporcionado por el intercambio efímero", ["La compresión HTTP", "El almacenamiento de cookies", "La ausencia de autenticación"], "TLS 1.3 usa intercambios efímeros para proporcionar forward secrecy en las suites definidas.", "RFC 8446, secciones 2 y 4", "concept", "advanced"),
        fact("¿Qué componente del handshake de TLS 1.3 permite negociar versión y parámetros?", "ClientHello y ServerHello", ["Solo el mensaje Finished del cliente", "El registro DNS", "La cabecera MIME"], "ClientHello y ServerHello negocian la versión, capacidades y parámetros criptográficos antes de proteger la aplicación.", "RFC 8446, sección 4.1", "procedure", "intermediate"),
        fact("¿Qué tipo de cifrado usa la misma clave secreta para cifrar y descifrar?", "El cifrado simétrico", ["El cifrado asimétrico", "El hash unidireccional", "La codificación Base64"], "Los algoritmos simétricos emplean una clave compartida; los asimétricos emplean un par de claves.", "RFC 8446, sección 5 y terminología criptográfica", "concept", "basic"),
        fact("¿Qué garantiza un código de autenticación asociado a un cifrado AEAD?", "Confidencialidad e integridad autenticada del texto cifrado", ["Solo compresión", "Únicamente anonimato de la red", "La disponibilidad del servidor"], "Las construcciones AEAD combinan cifrado con autenticación de datos asociados para detectar modificaciones.", "RFC 8446, sección 5.2", "concept", "intermediate"),
        fact("¿Qué paquete OpenPGP contiene normalmente la firma digital?", "Un paquete de firma", ["Un paquete de imagen", "Un paquete DNS", "Un paquete de sesión HTTP"], "RFC 9580 define el Signature Packet para transportar una firma y sus metadatos.", "RFC 9580, sección 5.2", "concept", "basic"),
        fact("¿Qué operación permite recuperar la clave pública de un certificado emitido por una CA?", "La validación de la cadena de certificación", ["La compresión del certificado", "La eliminación de la firma de la CA", "El cambio del algoritmo de hash"], "La cadena de confianza permite validar la firma de la CA y usar la clave pública contenida en el certificado.", "RFC 5280, sección 6", "procedure", "advanced"),
        fact("¿Qué uso de clave X.509 indica que una clave puede emplearse para autenticación de servidor?", "La extensión Extended Key Usage con serverAuth", ["La extensión Basic Constraints con cA=false por sí sola", "El campo Subject vacío", "La extensión CRL Distribution Points sin más"], "RFC 5280 define serverAuth como uso extendido para autenticación de servidor TLS.", "RFC 5280, sección 4.2.1.12", "concept", "advanced"),
        fact("¿Qué ventaja aporta la separación entre clave de firma y clave de cifrado?", "Reduce la mezcla de usos y permite aplicar políticas criptográficas distintas", ["Elimina la necesidad de proteger la clave privada", "Hace innecesaria la revocación", "Convierte todo cifrado en simétrico"], "Separar usos facilita aplicar las restricciones de Key Usage y gestionar la confianza de forma más segura.", "RFC 5280, sección 4.2.1.3", "scenario", "intermediate"),
